# ❌ OLD: Omitting @wraps destroys function introspection.
# Sentry, logging, and documentation tools see all functions as 'wrapper'!
def timer(fn):
  def wrapper(*args, **kwargs):
    return fn(*args, **kwargs)
  return wrapper

@timer
def calculate_tax(amount: float) -> float:
  """Calculates sales tax."""
  return amount * 0.2

print(calculate_tax.__name__) # ❌ Prints 'wrapper' instead of 'calculate_tax'!
print(calculate_tax.__doc__)  # ❌ Prints None instead of docstring!

import functools
import time

# ✅ NEW: Parameterized decorator preserving all metadata and __wrapped__ reference
def log_execution(prefix: str = 'LOG'):
  def decorator(fn):
    @functools.wraps(fn) # ✅ Preserves __name__, __doc__, __annotations__
    def wrapper(*args, **kwargs):
      start = time.perf_counter()
      result = fn(*args, **kwargs)
      print(f'[{prefix}] {fn.__name__} took {time.perf_counter() - start:.4f}s')
      return result
    return wrapper
  return decorator

@log_execution(prefix='METRICS')
def calculate_tax(amount: float) -> float:
  """Calculates sales tax."""
  return amount * 0.2

print(calculate_tax.__name__) # ✅ 'calculate_tax'
print(calculate_tax.__doc__)  # ✅ 'Calculates sales tax.'
print(calculate_tax.__wrapped__) # Access original unwrapped function!
